/// <summary>
///Return order and claims Business events
/// </summary>
[BusinessEvents(classStr(METSOReturnAndClaimsBusinessEventContract), 'Sales order return and claims', 'This business event is triggered when the return order lines are registered', ModuleAxapta::SalesOrder)]
public final class METSOReturnAndClaimsBusinessEvent extends BusinessEventsBase
{
    private SalesTable salestable;
}

Method.Source:
/// <summary>
/// Constructs a new METSOReturnAndClaimsBusinessEventContract business event data contract.
/// </summary>
/// <returns>
/// A new <c>METSOReturnAndClaimsBusinessEventContract</c> business event data contract.
/// </returns>
[Wrappable(true), Replaceable(true)]
public BusinessEventsContract buildContract()
{
    return METSOReturnAndClaimsBusinessEventContract::newFromSalesTable(salestable);
}

    /// <summary>
    /// Parameter method for sales table
    /// </summary>
    /// <param name = "_salesTable">SalesTable reference</param>
    /// <returns>SalesTable</returns>
    public SalesTable parmSalesTable(SalesTable _salesTable = salestable)
    {
        salestable = _salesTable;

        return salestable;
    }

    /// <summary>
    /// Creates a <c>METSOReadyForPricingBusinessEvent</c> from a <c>SalesTable</c> record.
    /// </summary>
    /// <param name = "_salesTable"> A sales order record.</param>
    /// <returns>An instance of <c>METSOReadyForPricingBusinessEvent</c>.</returns>
    public static METSOReturnAndClaimsBusinessEvent newFromSalesTable(SalesTable _salesTable)
    {
        METSOReturnAndClaimsBusinessEvent businessEvent = new METSOReturnAndClaimsBusinessEvent();
        businessEvent.parmSalesTable(_salesTable);

        return businessEvent;
    }
